exercises.solution:
async function processInChunks(items, chunkSize, fn) {
  const out = [];
  for (let i = 0; i < items.length; i += chunkSize) {
    for (const item of items.slice(i, i + chunkSize)) out.push(fn(item));
    if (i + chunkSize < items.length) {
      await new Promise(res => setTimeout(res, 0)); // yield to the loop
    }
  }
  return out;
}

(async () => {
  setTimeout(() => console.log('probe: event loop responsive'), 0);
  const results = await processInChunks([1, 2, 3, 4, 5, 6, 7], 3, x => x * 2);
  console.log('results:', results.join(','));
})();

exercises.prompt:
Microtasks are fast — but a pure-microtask drain starves timers, I/O, and rendering (lesson 2). Implement `drainFair(items, fn, budget)`: process items via microtask-speed iteration, but yield to a macrotask every `budget` items so the loop stays responsive.

Contrast it with a naive all-microtask drain. Each demo schedules a probe `setTimeout` *before* draining and records how many items were processed when the probe fires:

```js
function drainNaive(items, fn) {
  return new Promise(resolve => {
    let i = 0;
    (function step() {
      if (i >= items.length) return resolve();
      fn(items[i++]);
      queueMicrotask(step);
    })();
  });
}

async function drainFair(items, fn, budget) {
  // ... same iteration, but await a setTimeout(0) yield every `budget` items
}

(async () => {
  const items = Array.from({ length: 1000 }, (_, i) => i);
  const sleep0 = () => new Promise(r => setTimeout(r, 0));

  let naiveProcessed = 0;
  setTimeout(() => console.log(`naive drain: probe fired after ${naiveProcessed}/1000 items — timers starved`), 0);
  await drainNaive(items, () => { naiveProcessed++; });
  await sleep0(); // let the starved probe fire before the next phase

  let fairProcessed = 0;
  setTimeout(() => console.log(`fair drain:  probe fired after ${fairProcessed}/1000 items — loop stayed responsive`), 0);
  await drainFair(items, () => { fairProcessed++; }, 250);
})();
```

Expected solution output:
```
naive drain: probe fired after 1000/1000 items — timers starved
fair drain:  probe fired after 250/1000 items — loop stayed responsive
```

